on/pass/lib/shares/share.requests';\nimport { encodeVaultContent } from '@proton/pass/lib/vaults/vault-proto.transformer';\nimport type { VaultTransferOwnerIntent } from '@proton/pass/types';\nimport { type Share, type ShareContent, type ShareType, type VaultCreateRequest } from '@proton/pass/types';\n\nexport const createVault = async (data: {\n    content: ShareContent<ShareType.Vault>;\n}): Promise<Share<ShareType.Vault>> => {\n    const encoded = encodeVaultContent(data.content);\n    const encryptedVault: VaultCreateRequest = { ...(await PassCrypto.createVault(encoded)) };\n\n    const encryptedShare = (\n        await api({\n            url: 'pass/v1/vault',\n            method: 'post',\n            data: encryptedVault,\n        })\n    ).Share!;\n\n    const share = await parseShareResponse(encryptedShare);\n    if (!share) throw new Error(c('Error').t`Could not open created vault`);\n\n    return share;\n};\n\nexport const editVault = async (\n    shareId: string,\n    content: ShareContent<ShareType.Vault>\n): Promise<Share<ShareType.Vault>> => {\n    /* Future-proofing : retrieve all share keys\n     * and update the share in the crypto context */\n    const shareKeys = await getAllShareKeys(shareId);\n    await PassCrypto.updateShareKeys({ shareId, shareKeys });\n\n    const encoded = encodeVaultContent(content);\n    const encryptedVaultUpdate = await PassCrypto.updateVault({ shareId, content: encoded });\n\n    const encryptedShare = (\n        await api({\n            url: `pass/v1/vault/${shareId}`,\n            method: 'put',\n            data: encryptedVaultUpdate,\n        })\n    ).Share!;\n\n    const share = await parseShareResponse(encryptedShare, { shareKeys });\n    if (!share) throw new Error(c('Error').t`Could not open updated vault`);\n\n    return share;\n};\n\nexport const deleteVault = async (shareId: string) => api({ url: `pass/v1/vault/${shareId}`, method: 'delete' });\n\nexport const vaultTransferOwner = async ({ shareId, userShareId }: VaultTransferOwnerIntent) =>\n    api({\n        url: `pass/v1/vault/${shareId}/owner`,\n        method: 'put',\n        data: { NewOwnerShareID: userShareId },\n    });\n","/** The Unix epoch (or Unix time or POSIX time or Unix timestamp) is\n * the number of seconds that have elapsed since January 1, 1970\n * (midnight UTC/GMT) */\nexport const getEpoch = (): number => Math.round(new Date().getTime() / 1_000);\nexport const epochToMs = (s: number) => s * 1_000;\nexport const msToEpoch = (ms: number) => Math.floor(ms / 1_000);\nexport const epochToDate = (s: number): Date => new Date(s * 1_000);\n","import type { AsyncCallback } from '@proton/pass/types';\nimport { getEpoch } from '@proton/pass/utils/time/epoch';\nimport lastItem from '@proton/utils/lastItem';\n\ntype MaxAgeMemoizeOptions = { maxAge: number };\n\nexport type MaxAgeMemoizedFn<F extends AsyncCallback> = (\n    ...args: [...Parameters<F>, options: MaxAgeMemoizeOptions]\n) => ReturnType<F>;\n\n/** Memoizes the result of an asynchronous function with a specified maximum age.\n * Returns a wrapped function that accepts a trailing `maxAge` parameter in seconds */\nexport const maxAgeMemoize = <F extends AsyncCallback>(fn: F) => {\n    const cache: Map<string, { calledAt: number; result: ReturnType<F> }> = new Map();\n\n    return (async (...args: [...Parameters<F>, options: MaxAgeMemoizeOptions]) => {\n        const calledAt = getEpoch();\n        const { maxAge } = lastItem(args) as MaxAgeMemoizeOptions;\n\n        const memoArgs = JSON.stringify(args.slice(0, -1));\n        const cached = cache.get(memoArgs);\n\n        if (cached && calledAt - cached.calledAt < maxAge) return cached.result;\n        else {\n            const result = await fn(...args);\n            cache.set(memoArgs, { calledAt, result });\n            return result;\n        }\n    }) as MaxAgeMemoizedFn<F>;\n};\n","/**\n * Returns the last item in an array\n */\nexport default function lastItem<T>(array: ArrayLike<T>): T | undefined {\n    return array[array.length - 1];\n}\n","const compare = <T>(a: T, b: T): number => {\n    if (typeof a === 'string' && typeof b === 'string') return a.localeCompare(b);\n    if (typeof a === 'number' && typeof b === 'number') return a - b;\n    return 0; /* else cannot compare */\n};\n\nexport const sortOn =\n    <T extends { [key: string]: any }, K extends keyof T>(key: K, order: 'ASC' | 'DESC' = 'DESC') =>\n    (a: T, b: T): number =>\n        order === 'DESC' ? compare(b[key], a[key]) : compare(a[key], b[key]);\n","import { getAliasOptions } from '@proton/pass/lib/alias/alias.requests';\nimport { exposeApi } from '@proton/pass/lib/api/api';\nimport { exposePassCrypto } from '@proton/pass/lib/crypto';\nimport { createPassCrypto } from '@proton/pass/lib/crypto/pass-crypto';\nimport { parseItemRevision } from '@proton/pass/lib/items/item.parser';\nimport { createAlias, requestAllItemsForShareId } from '@proton/pass/lib/items/item.requests';\nimport { parseShareResponse } from '@proton/pass/lib/shares/share.parser';\nimport { requestShares } from '@proton/pass/lib/shares/share.requests';\nimport { getUserAccess } from '@proton/pass/lib/user/user.requests';\nimport { isActiveVault, isOwnVault, isWritableVault } from '@proton/pass/lib/vaults/vault.predicates';\nimport { createVault } from '@proton/pass/lib/vaults/vault.requests';\nimport type { ItemRevision, Api as PassApi } from '@proton/pass/types';\nimport { first } from '@proton/pass/utils/array/first';\nimport { prop } from '@proton/pass/utils/fp/lens';\nimport { maxAgeMemoize } from '@proton/pass/utils/fp/memo';\nimport { pipe } from '@proton/pass/utils/fp/pipe';\nimport { and, truthy } from '@proton/pass/utils/fp/predicates';\nimport { sortOn } from '@proton/pass/utils/fp/sort';\nimport { waitUntil } from '@proton/pass/utils/fp/wait-until';\nimport { obfuscate } from '@proton/pass/utils/obfuscate/xor';\nimport { uniqueId } from '@proton/pass/utils/string/unique-id';\nimport { getEpoch } from '@proton/pass/utils/time/epoch';\nimport type { Api } from '@proton/shared/lib/interfaces';\nimport unary from '@proton/utils/unary';\n\nimport type { PassBridge, PassBridgeAliasItem } from './types';\n\nlet passBridgeInstance: PassBridge | undefined;\n\nexport const createPassBridge = (api: Api): PassBridge => {\n    return (\n        passBridgeInstance ||\n        (() => {\n            exposeApi(api as PassApi);\n            const PassCrypto = exposePassCrypto(createPassCrypto());\n\n            passBridgeInstance = {\n                init: async ({ user, addresses, authStore }) => {\n                    await PassCrypto.hydrate({ user, addresses, keyPassword: authStore.getPassword(), clear: false });\n                    const isReady = await waitUntil(() => PassCrypto.ready, 250).then(() => true);\n\n                    return isReady;\n                },\n                user: {\n                    getUserAccess: maxAgeMemoize(async () => {\n                        const result = await getUserAccess();\n                        return result;\n                    }),\n                },\n                vault: {\n                    getDefault: maxAgeMemoize(async (hadVaultCallback) => {\n                        const encryptedShares = await requestShares();\n                        const shares = (await Promise.all(encryptedShares.map(unary(parseShareResponse)))).filter(\n                            truthy\n                        );\n                        const candidates = shares\n                            .filter(and(isActiveVault, isWritableVault, isOwnVault))\n                            .sort(sortOn('createTime', 'ASC'));\n\n                        const defaultVault = first(candidates);\n                        if (defaultVault) {\n                            hadVaultCallback?.(true);\n                            return defaultVault;\n                        } else {\n                            hadVaultCallback?.(false);\n                            const newVault = await createVault({\n                                content: {\n                                    name: 'Personal',\n                                    description: 'Personal vault (created from Mail)',\n                                    display: {},\n                                },\n                            });\n                            return newVault;\n                        }\n                    }),\n                },\n                alias: {\n                    create: async ({ shareId, name, note, alias: { aliasEmail, mailbox, prefix, signedSuffix } }) => {\n                        const itemUuid = uniqueId();\n\n                        const encryptedItem = await createAlias({\n                            content: {},\n                            createTime: getEpoch(),\n                            extraData: { aliasEmail, mailboxes: [mailbox], prefix, signedSuffix },\n                            extraFields: [],\n                            metadata: { itemUuid, name, note: obfuscate(note ?? '') },\n                            optimisticId: itemUuid,\n                            shareId,\n                            type: 'alias',\n                        });\n\n                        const item = (await parseItemRevision(shareId, encryptedItem)) as ItemRevision<'alias'>;\n\n                        return {\n                            item: { ...item, aliasEmail },\n                        };\n                    },\n                    getAliasOptions: getAliasOptions,\n                    getAllByShareId: maxAgeMemoize(async (shareId) => {\n                        const aliases = (await Promise.all(\n                            (await requestAllItemsForShareId({ shareId, OnlyAlias: true }))\n                                .filter(pipe(prop('AliasEmail'), truthy))\n                                .map((item) => parseItemRevision(shareId, item))\n                        )) as ItemRevision<'alias'>[];\n\n                        return aliases.map((item): PassBridgeAliasItem => ({ item }));\n                    }),\n                },\n            };\n\n            return passBridgeInstance;\n        })()\n    );\n};\n","type WaitUntilCallback = (() => boolean) | { check: () => boolean; cancel: () => boolean };\n\nexport const waitUntil = (cb: WaitUntilCallback, refresh: number, timeout: number = 5_000): Promise<void> => {\n    const check = typeof cb === 'function' ? cb : cb.check;\n    const cancel = typeof cb === 'function' ? undefined : cb.cancel;\n\n    let timer: NodeJS.Timeout;\n    let interval: NodeJS.Timeout;\n\n    const clear = () => {\n        clearTimeout(timer);\n        clearInterval(interval);\n    };\n\n    return new Promise<void>((resolve, reject) => {\n        if (cancel?.()) return reject();\n        if (check()) return resolve();\n\n        timer = setTimeout(() => reject(clear()), timeout);\n        interval = setInterval(() => {\n            if (cancel?.()) return reject(clear());\n            if (!check()) return;\n            resolve(clear());\n        }, refresh);\n    });\n};\n","import { type Maybe } from '@proton/pass/types';\n\nexport const first = <T>(arr: T[]): Maybe<T> => arr?.[0];\n","export const uniqueId = (length: number = 8): string =>\n    Array.from(crypto.getRandomValues(new Uint8Array(length)))\n        .map((b) => b.toString(16))\n        .join('')\n        .slice(0, length);\n","export const prop =\n    <T extends { [key: string]: any }, K extends keyof T>(key: K) =>\n    (obj: T): T[K] =>\n        obj[key];\n\nexport const withPayload =\n    <T extends { payload: any }, F extends (payload: T['payload']) => any>(fn: F) =>\n    (obj: T): ReturnType<F> =>\n        fn(obj.payload);\n\nexport const withPayloadLens =\n    <\n        T extends { payload: { [key: string]: any } },\n        K extends keyof T['payload'],\n        F extends (payload: T['payload'][K]) => any\n    >(\n        prop: K,\n        fn: F\n    ) =>\n    (obj: T): ReturnType<F> =>\n        fn(obj.payload[prop as any]);\n","import type { FC, PropsWithChildren } from 'react';\nimport { createContext, useContext } from 'react';\n\nimport { useApi } from '@proton/components/hooks';\nimport useInstance from '@proton/hooks/useInstance';\nimport type { MaybeNull } from '@proton/pass/types';\n\nimport { createPassBridge } from '.';\nimport type { PassBridge } from './types';\n\nexport const PassBridgeContext = createContext<MaybeNull<PassBridge>>(null);\n\nexport const PassBridgeProvider: FC<PropsWithChildren> = ({ children }) => {\n    const api = useApi();\n    const bridge = useInstance(() => createPassBridge(api));\n\n    return <PassBridgeContext.Provider value={bridge}>{children}</PassBridgeContext.Provider>;\n};\n\nexport const usePassBridge = () => {\n    const passBridge = useContext(PassBridgeContext);\n    if (!passBridge) throw new Error('PassBridge was not instantiated');\n    return passBridge;\n};\n","import { c } from 'ttag';\n\nimport { Card } from '@proton/atoms/Card';\nimport { Copy, Info } from '@proton/components/components';\nimport { useNotifications } from '@proton/components/hooks';\nimport type { PassBridgeAliasItem } from '@proton/pass/lib/bridge/types';\n\nimport { DrawerAppHeadline } from '../../shared';\n\ntype FilteredAlias = { name: string; alias: string };\nconst getFilteredAliases = (items: PassBridgeAliasItem[]): FilteredAlias[] => {\n    return items.reduce<FilteredAlias[]>((acc, item) => {\n        const alias = item.item.aliasEmail;\n        const name = item.item.data.metadata.name;\n\n        if (alias) {\n            acc.push({ name, alias });\n        }\n\n        return acc;\n    }, []);\n};\n\ninterface Props {\n    items: PassBridgeAliasItem[];\n}\n\nconst PassAliasesList = ({ items }: Props) => {\n    const { createNotification } = useNotifications();\n    const aliases = getFilteredAliases(items).slice(0, 3);\n\n    const handleCopy = () => {\n        createNotification({\n            text: c('Success').t`Alias copied to clipboard`,\n        });\n    };\n\n    return (\n        <>\n            <DrawerAppHeadline className=\"mb-1\">\n                {c('Security Center').t`Hide-my-email aliases`}{' '}\n                <Info className=\"mb-1\" title={c('Success').t`Last modified aliases stored in your oldest vault`} />\n            </DrawerAppHeadline>\n            <div className=\"flex flex-column flex-nowrap gap-y-2 max-w-full\">\n                {aliases.map(({ alias, name }) => (\n                    <Card\n                        rounded\n                        key={alias}\n                        padded={false}\n                        data-testid=\"pass-aliases-item\"\n                        className=\"relative p-3 border-weak flex flex-nowrap items-center\"\n                    >\n                        <div className=\"flex-1 pr-2\">\n                            <span className=\"block color-weak text-ellipsis\" title={name}>\n                                {name}\n                            </span>\n                            <span className=\"block text-ellipsis flex-1\" title={alias}>\n                                {alias}\n                            </span>\n                        </div>\n                        <Copy\n                            data-testid=\"pass-aliases-item:copy-button\"\n                            size=\"small\"\n                            shape=\"ghost\"\n                            value={alias}\n                            className=\"shrink-0 expand-click-area\"\n                            onCopy={handleCopy}\n                        />\n                    </Card>\n                ))}\n            </div>\n        </>\n    );\n};\n\nexport default PassAliasesList;\n","import React from 'react';\n\nimport { c } from 'ttag';\n\nimport { Href } from '@proton/atoms/Href';\nimport { getKnowledgeBaseUrl } from '@proton/shared/lib/helpers/url';\nimport aliasSampleSvg from '@proton/styles/assets/img/illustrations/pass-aliases-alias-sample.svg';\n\nimport { DrawerAppHeadline } from '../../shared';\n\nconst HasNoAliases = () => {\n    const learnMoreLink = (\n        <Href\n            key=\"pass-aliases-support\"\n            className=\"inline-block\"\n            href={getKnowledgeBaseUrl('/addresses-and-aliases')}\n        >{c('Link').t`Learn more`}</Href>\n    );\n\n    return (\n        <div className=\"text-center mt-1\">\n            <img src={aliasSampleSvg} alt=\"\" className=\"w-full mb-3\" />\n            <DrawerAppHeadline>{c('Security Center').t`Protect your online identity`}</DrawerAppHeadline>\n            <p className=\"m-0 mt-2 text-sm color-weak\">{c('Security Center')\n                .jt`Hide-my-email aliases let you sign up for things online without sharing your email address. ${learnMoreLink}`}</p>\n        </div>\n    );\n};\n\nexport default HasNoAliases;\n","import { getApiError, getApiErrorMessage } from '@proton/shared/lib/api/helpers/apiErrorHelper';\nimport { ApiError } from '@proton/shared/lib/fetch/ApiError';\n\nexport enum PASS_ALIASES_ERROR_STEP {\n    /** Failed to init the pass bridge */\n    INIT_BRIDGE = 'PassAliasesInitError',\n    /** Failed to create an alias */\n    CREATE_ALIAS = 'PassAliasesCreateError',\n}\n\nexport class PassAliasesError extends Error {\n    constructor(error: Error, step: PASS_ALIASES_ERROR_STEP) {\n        let name = error?.name ? error.name + ':' : '';\n        let message = error?.message || '';\n\n        if (error instanceof ApiError) {\n            const sentryError = getApiError(error);\n            const errorCode = sentryError?.code ? ` ${sentryError.code}` : '';\n            name = `API Error${errorCode}` + ' - ' + name;\n\n            if (sentryError?.message && sentryError?.code >= 400 && sentryError?.code < 500) {\n                message = getApiErrorMessage(error) || message;\n            }\n        }\n\n        super(`${name} ${message}`);\n\n        this.name = step;\n        this.stack = error.stack;\n    }\n}\n\nexport default PassAliasesError;\n","import { type FormikErrors } from 'formik';\nimport { c } from 'ttag';\n\nimport type { SanitizedAliasOptions } from '@proton/pass/hooks/useAliasOptions';\nimport type {\n    AliasFormValues,\n    EditAliasFormValues,\n    LoginItemFormValues,\n    MaybeNull,\n    NewAliasFormValues,\n} from '@proton/pass/types';\nimport { validateLocalPart } from '@proton/shared/lib/helpers/email';\nimport { normalize } from '@proton/shared/lib/helpers/string';\n\nimport { validateItemErrors } from './item';\n\n/* Normalize unicode representation of the string\n * Remove diacritics (accents) + 20 max characters length\n * for the auto-derived alias name.\n * Removes trailing/leading dots. */\nexport const deriveAliasPrefix = (name: string) => {\n    const prefix = normalize(name, true)\n        .replace(/[^a-z0-9\\-\\_.]/g, '')\n        .slice(0, 20);\n\n    return prefix.replace(/\\.*$/, '').replace(/^\\.+/, '');\n};\n\nexport const validateAliasForm = ({\n    aliasPrefix,\n    mailboxes,\n    aliasSuffix,\n}: AliasFormValues): FormikErrors<AliasFormValues> => {\n    const errors: FormikErrors<AliasFormValues> = {};\n\n    if (aliasPrefix === undefined || !validateLocalPart(aliasPrefix + (aliasSuffix?.value?.split('@')?.[0] ?? ''))) {\n        errors.aliasPrefix = c('Warning').t`Invalid alias prefix`;\n    }\n\n    if (aliasSuffix === undefined) {\n        errors.aliasSuffix = c('Warning').t`Missing alias suffix`;\n    }\n\n    if (mailboxes.length === 0) {\n        errors.mailboxes = c('Warning').t`You must select at least one mailbox`;\n    }\n\n    return errors;\n};\n\nexport const validateNewAliasForm = (values: NewAliasFormValues): FormikErrors<NewAliasFormValues> => {\n    const errors: FormikErrors<NewAliasFormValues> = { ...validateItemErrors(values), ...validateAliasForm(values) };\n    const { aliasPrefix, aliasSuffix, mailboxes } = values;\n\n    if (aliasPrefix === undefined || aliasPrefix.trim() === '') {\n        errors.aliasPrefix = c('Warning').t`Missing alias prefix`;\n    }\n\n    if (aliasPrefix && !validateLocalPart(aliasPrefix + (aliasSuffix?.value?.split('@')?.[0] ?? ''))) {\n        errors.aliasPrefix = c('Warning').t`Invalid alias prefix`;\n    }\n\n    if (aliasPrefix && !/^[a-z0-9\\-\\_.]*$/.test(aliasPrefix)) {\n        errors.aliasPrefix = c('Warning').t`Only alphanumeric characters, dots, hyphens and underscores are allowed`;\n    }\n\n    if (aliasPrefix && aliasPrefix.length > 40) {\n        errors.aliasPrefix = c('Warning').t`The alias prefix cannot be longer than 40 characters`;\n    }\n\n    if (aliasSuffix === undefined) {\n        errors.aliasSuffix = c('Warning').t`Missing alias suffix`;\n    }\n\n    if (mailboxes.length === 0) {\n        errors.mailboxes = c('Warning').t`You must select at least one mailbox`;\n    }\n\n    return errors;\n};\n\nexport const createEditAliasFormValidator =\n    (aliasOwner: boolean) =>\n    (values: EditAliasFormValues): FormikErrors<EditAliasFormValues> => {\n        const errors: FormikErrors<EditAliasFormValues> = validateItemErrors(values);\n\n        if (aliasOwner && values.mailboxes.length === 0) {\n            errors.mailboxes = c('Warning').t`You must select at least one mailbox`;\n        }\n\n        return errors;\n    };\n\nexport const reconciliateAliasFromDraft = <V extends AliasFormValues>(\n    aliasValues: V,\n    aliasOptions: MaybeNull<SanitizedAliasOptions>,\n    fallback?: Partial<AliasFormValues>\n): AliasFormValues => {\n    const { aliasSuffix, mailboxes, aliasPrefix } = aliasValues;\n    const suffixOptions = aliasOptions?.suffixes ?? [];\n    const mailboxOptions = aliasOptions?.mailboxes ?? [];\n\n    const suffixMatch = suffixOptions.find(({ signature }) => signature === aliasSuffix?.signature);\n    const mailboxesMatch = mailboxOptions.filter(({ id }) => mailboxes.some((mailbox) => id === mailbox.id));\n\n    return {\n        aliasPrefix: aliasPrefix,\n        aliasSuffix: suffixMatch ?? fallback?.aliasSuffix,\n        mailboxes: mailboxesMatch.length > 0 ? mailboxesMatch : fallback?.mailboxes ?? [],\n    };\n};\n\nexport const sanitizeLoginAliasSave = (formData: LoginItemFormValues): LoginItemFormValues => {\n    const { username, aliasPrefix, aliasSuffix } = formData;\n\n    if (aliasSuffix !== undefined && username !== `${aliasPrefix}${aliasSuffix.value}`) {\n        return {\n            ...formData,\n            withAlias: false,\n            aliasPrefix: '',\n            aliasSuffix: undefined,\n            mailboxes: [],\n        };\n    }\n\n    return formData;\n};\n\nexport const sanitizeLoginAliasHydration =\n    (aliasOptions: MaybeNull<SanitizedAliasOptions>) =>\n    (formData: LoginItemFormValues): LoginItemFormValues => {\n        if (!formData.withAlias) return formData;\n\n        const aliasValues = reconciliateAliasFromDraft(formData, aliasOptions);\n        const withAlias = aliasValues.aliasSuffix !== undefined && aliasValues.mailboxes.length > 0;\n        return { ...formData, ...aliasValues, withAlias, username: withAlias ? formData.username : '' };\n    };\n","import type { ItemIDRevision2 } from '@proton/pass/types/api/pass';\nimport type { OpenedItem } from '@proton/pass/types/crypto';\nimport type {\n    ExtraFieldType,\n    ItemType,\n    Metadata,\n    ProtobufItemAlias,\n    ProtobufItemCreditCard,\n    ProtobufItemLogin,\n    ProtobufItemNote,\n} from '@proton/pass/types/protobuf';\nimport type { ExtraHiddenField, ExtraTotp, PlatformSpecific } from '@proton/pass/types/protobuf/item-v1';\nimport type { MaybeNull } from '@proton/pass/types/utils';\nimport type { SanitizedBuffers } from '@proton/pass/utils/buffer/sanitization';\nimport type { XorObfuscation } from '@proton/pass/utils/obfuscate/xor';\n\ntype Obfuscate<T, K extends keyof T> = Omit<T, K> & { [Obf in K]: XorObfuscation };\n\ntype Deobfuscate<T> = {\n    [K in keyof T]: T[K] extends XorObfuscation\n        ? string\n        : T[K] extends ArrayBuffer\n          ? T[K]\n          : T[K] extends (infer U)[]\n            ? Deobfuscate<U>[]\n            : T[K] extends {}\n              ? Deobfuscate<T[K]>\n              : T[K];\n};\n\ntype ExtraFieldContent<T extends ExtraFieldType> = {\n    totp: Obfuscate<ExtraTotp, 'totpUri'>;\n    text: Obfuscate<ExtraHiddenField, 'content'>;\n    hidden: Obfuscate<ExtraHiddenField, 'content'>;\n}[T];\n\nexport type ItemContent<T extends ItemType> = {\n    alias: ProtobufItemAlias;\n    note: ProtobufItemNote;\n    login: Obfuscate<SanitizedBuffers<ProtobufItemLogin>, 'username' | 'password' | 'totpUri'>;\n    creditCard: Obfuscate<ProtobufItemCreditCard, 'number' | 'verificationNumber' | 'pin'>;\n}[T];\n\nexport type UnsafeItemContent<T extends ItemType = ItemType> = Deobfuscate<ItemContent<T>>;\n\nexport type ItemExtraField<T extends ExtraFieldType = ExtraFieldType> = {\n    [Key in T]: {\n        fieldName: string;\n        type: Key;\n        data: ExtraFieldContent<Key>;\n    };\n}[T];\n\nexport type UnsafeItemExtraField<T extends ExtraFieldType = ExtraFieldType> = Deobfuscate<ItemExtraField<T>>;\n\n/**\n * Derives a generic \"distributive object type\" over all possible\n * oneofKind keys - This will allow us to create generic functions\n * and \"object mappers\" over every item type derived from the original\n * protoc-gen-ts generated types\n *\n * Item types can be extended via an \"Extra\" type (an object type indexed\n * on ItemType keys) - this will let us create \"qualified\" generics over\n * the base Item type (see ./items.dto.ts for an example)\n */\nexport type Item<T extends ItemType = ItemType, ExtraData extends { [K in T]?: any } = never> = {\n    [Key in T]: {\n        type: Key;\n        content: ItemContent<Key>;\n        platformSpecific?: PlatformSpecific;\n        extraFields: ItemExtraField[];\n        metadata: Obfuscate<Metadata, 'note'>;\n    } & (ExtraData[Key] extends never ? {} : { extraData: ExtraData[Key] });\n}[T];\n\nexport type UnsafeItem<T extends ItemType = ItemType> = Deobfuscate<Item<T>>;\n\nexport enum ItemState {\n    Active = 1,\n    Trashed = 2,\n}\n\nexport type ItemRevision<T extends ItemType = ItemType> = Omit<OpenedItem, 'content'> & {\n    data: Item<T>;\n    shareId: string;\n};\n\nexport type ItemRevisionID = ItemIDRevision2;\n\nexport type UnsafeItemRevision<T extends ItemType = ItemType> = Deobfuscate<ItemRevision<T>>;\n\n/**\n * Adds an optimistic & failed property to\n * the ItemRevision type\n */\nexport type ItemRevisionWithOptimistic<T extends ItemType = ItemType> = ItemRevision<T> & {\n    optimistic: boolean;\n    failed: boolean;\n};\n\n/**\n * Generic utility type to construct\n * item key mappers over the different item types\n */\nexport type ItemMap<T> = { [type in ItemType]: T };\n\nexport type UniqueItem = { shareId: string; itemId: string };\nexport type SelectedItem = UniqueItem;\n\nexport type ItemSortFilter = 'recent' | 'titleASC' | 'createTimeDESC' | 'createTimeASC';\nexport type ItemTypeFilter = '*' | ItemType;\n\nexport type ItemFilters = {\n    search: string;\n    selectedShareId: MaybeNull<string>;\n    sort: ItemSortFilter;\n    type: ItemTypeFilter;\n};\n\nexport type IndexedByShareIdAndItemId<T> = { [shareId: string]: { [itemId: string]: T } };\n\nexport type BatchItemRevisionIDs = { shareId: string; batch: ItemRevisionID[] };\nexport type BatchItemRevisions = { shareId: string; batch: ItemRevision[] };\n","import type { Draft, EditDraft, NewDraft } from '@proton/pass/store/reducers';\nimport { type Item, type ItemRevision, ItemState, type UniqueItem } from '@proton/pass/types';\n\nexport const isLoginItem = (item: Item): item is Item<'login'> => item.type === 'login';\nexport const isAliasItem = (item: Item): item is Item<'alias'> => item.type === 'alias';\nexport const isNoteItem = (item: Item): item is Item<'note'> => item.type === 'note';\n\nexport const isPasskeyItem = (item: Item): item is Item<'login'> =>\n    isLoginItem(item) && (item.content.passkeys ?? []).length > 0;\n\nexport const itemEq =\n    <T extends UniqueItem>(a: T) =>\n    (b: T): boolean =>\n        a.shareId === b.shareId && a.itemId === b.itemId;\n\nexport const belongsToShare =\n    (shareId: string) =>\n    <T extends UniqueItem>(item: T): boolean =>\n        item.shareId === shareId;\n\nexport const isTrashed = ({ state }: ItemRevision) => state === ItemState.Trashed;\n\nexport const isEditItemDraft = (draft?: Draft): draft is EditDraft => draft?.mode === 'edit';\nexport const isNewItemDraft = (draft?: Draft): draft is NewDraft => draft?.mode === 'new';\n\nexport const isPinned = ({ pinned }: ItemRevision) => pinned;\n","import type { PassBridgeAliasItem } from '@proton/pass/lib/bridge/types';\nimport { isTrashed } from '@proton/pass/lib/items/item.predicates';\n\nexport const filterPassAliases = (aliases: PassBridgeAliasItem[]) => {\n    const filterNonTrashedItems = ({ item }: PassBridgeAliasItem) => !isTrashed(item);\n    const sortDesc = (a: PassBridgeAliasItem, b: PassBridgeAliasItem) => {\n        const aTime = a.item.lastUseTime ?? a.item.revisionTime;\n        const bTime = b.item.lastUseTime ?? b.item.revisionTime;\n\n        return bTime - aTime;\n    };\n\n    return aliases.filter(filterNonTrashedItems).sort(sortDesc);\n};\n","import { createContext, useContext, useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { ModalStateReturnObj, useModalStateObject } from '@proton/components/components';\nimport { NOTIFICATION_DEFAULT_EXPIRATION_TIME } from '@proton/components/containers';\nimport { useAddresses, useAuthentication, useNotifications, useUser } from '@proton/components/hooks';\nimport useAsyncError from '@proton/hooks/useAsyncError';\nimport useIsMounted from '@proton/hooks/useIsMounted';\nimport { usePassBridge } from '@proton/pass/lib/bridge/PassBridgeProvider';\nimport type { PassBridgeAliasItem } from '@proton/pass/lib/bridge/types';\nimport { deriveAliasPrefix } from '@proton/pass/lib/validation/alias';\nimport { AliasOptions } from '@proton/pass/types';\nimport { UNIX_DAY, UNIX_MINUTE } from '@proton/pass/utils/time/constants';\nimport { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';\nimport { API_CUSTOM_ERROR_CODES } from '@proton/shared/lib/errors';\nimport { ApiError } from '@proton/shared/lib/fetch/ApiError';\nimport { textToClipboard } from '@proton/shared/lib/helpers/browser';\nimport { traceInitiativeError } from '@proton/shared/lib/helpers/sentry';\n\nimport { filterPassAliases } from './PassAliases.helpers';\nimport PassAliasesError, { PASS_ALIASES_ERROR_STEP } from './PassAliasesError';\nimport type { CreateModalFormState, PassAliasesVault } from './interface';\n\n/**\n * Memoize the pass aliases items to avoid displaying a loader on every drawer opening\n * In the long term we should have pass relying on the event loop.\n * However we decided to not go this way because implementation time\n */\nlet memoisedPassAliasesItems: PassBridgeAliasItem[] | null = null;\n\ninterface PasAliasesProviderReturnedValues {\n    /** Fetch needed options to be able to create a new alias request */\n    getAliasOptions: () => Promise<AliasOptions>;\n    /** If user has aliases saved in the currently decrypted vault */\n    hasAliases: boolean;\n    /** User had already a vault or not */\n    hasUsedProtonPassApp: boolean;\n    /** False when PassBridge finished to init and pass aliases values and count are done */\n    loading: boolean;\n    /** User already opened pass aliases drawer in the current session (not hard refreshed) */\n    hadInitialisedPreviously: boolean;\n    /** Has user reached pass aliases creation limit  */\n    hasReachedAliasesCountLimit: boolean;\n    submitNewAlias: (formValues: CreateModalFormState) => Promise<void>;\n    passAliasesVaultName: string;\n    /**\n     * Filtered and ordered list of pass aliases items\n     * Trashed items are not present\n     */\n    passAliasesItems: PassBridgeAliasItem[];\n    passAliasesUpsellModal: ModalStateReturnObj;\n}\n\nconst usePassAliasesSetup = (): PasAliasesProviderReturnedValues => {\n    const [user] = useUser();\n    const [addresses] = useAddresses();\n    const authStore = useAuthentication();\n    const PassBridge = usePassBridge();\n    const passAliasesUpsellModal = useModalStateObject();\n    const isMounted = useIsMounted();\n    const [loading, setLoading] = useState<boolean>(true);\n    const [passAliasVault, setPassAliasVault] = useState<PassAliasesVault>();\n    const [passAliasesItems, setPassAliasesItems] = useState<PassBridgeAliasItem[]>(memoisedPassAliasesItems || []);\n    const [totalVaultAliasesCount, setTotalVaultAliasesCount] = useState<number>(0);\n    const [passAliasesCountLimit, setPassAliasesCountLimit] = useState<number>(Number.MAX_SAFE_INTEGER);\n    const [userHadVault, setUserHadVault] = useState(false);\n    const { createNotification } = useNotifications();\n    const throwError = useAsyncError();\n\n    const submitNewAlias = async (formValues: CreateModalFormState) => {\n        try {\n            if (!passAliasVault) {\n                throw new Error('Vault should be defined');\n            }\n\n            // Submit to API\n            await PassBridge.alias.create({\n                shareId: passAliasVault.shareId,\n                name: formValues.name,\n                ...(formValues.note ? { note: formValues.note } : {}),\n                alias: {\n                    mailbox: formValues.mailbox,\n                    aliasEmail: formValues.alias,\n                    prefix: deriveAliasPrefix(formValues.name),\n                    signedSuffix: formValues.signedSuffix,\n                },\n            });\n\n            // Refetch aliases and set new state\n            const nextAliases = await PassBridge.alias.getAllByShareId(passAliasVault.shareId, {\n                maxAge: 0,\n            });\n            const filteredAliases = filterPassAliases(nextAliases);\n\n            if (isMounted()) {\n                setTotalVaultAliasesCount(nextAliases.length);\n                setPassAliasesItems(filteredAliases);\n                memoisedPassAliasesItems = filteredAliases;\n            }\n\n            textToClipboard(formValues.alias);\n            createNotification({\n                text: c('Success').t`Alias saved and copied`,\n                expiration: NOTIFICATION_DEFAULT_EXPIRATION_TIME,\n            });\n        } catch (error: any) {\n            if (\n                error instanceof ApiError &&\n                getApiError(error)?.code === API_CUSTOM_ERROR_CODES.CANT_CREATE_MORE_PASS_ALIASES\n            ) {\n                passAliasesUpsellModal.openModal(true);\n            } else {\n                const formattedError = new PassAliasesError(error, PASS_ALIASES_ERROR_STEP.CREATE_ALIAS);\n                // eslint-disable-next-line no-console\n                console.error(formattedError);\n                traceInitiativeError('drawer-security-center', formattedError);\n\n                // Because API displays a notification in case of error,\n                // here we manually display a notification in case no API errors are caught\n                if (!error.code) {\n                    createNotification({\n                        text: c('Error').t`An error occurred while saving your alias`,\n                        type: 'error',\n                        expiration: NOTIFICATION_DEFAULT_EXPIRATION_TIME,\n                    });\n                }\n            }\n        }\n    };\n\n    /**\n     * Returns needed data to create an alias\n     * @info Do not catch error here, it should be handled by the caller\n     */\n    const getAliasOptions = async () => {\n        if (!passAliasVault) {\n            throw new Error('Vault should be defined');\n        }\n        const options = await PassBridge.alias.getAliasOptions(passAliasVault.shareId);\n        return options;\n    };\n\n    const initPassBridge = async () => {\n        setLoading(true);\n        await PassBridge.init({ user, addresses: addresses || [], authStore });\n        let userHadVault = false;\n        const defaultVault = await PassBridge.vault.getDefault(\n            (hadVault) => {\n                userHadVault = hadVault;\n            },\n            { maxAge: UNIX_DAY * 1 }\n        );\n        const aliases = await PassBridge.alias.getAllByShareId(defaultVault.shareId, {\n            maxAge: UNIX_MINUTE * 5,\n        });\n        const userAccess = await PassBridge.user.getUserAccess({ maxAge: UNIX_MINUTE * 5 });\n        const filteredAliases = filterPassAliases(aliases);\n\n        if (isMounted()) {\n            setTotalVaultAliasesCount(aliases.length);\n            setPassAliasVault(defaultVault);\n            setPassAliasesCountLimit(userAccess.plan.AliasLimit ?? Number.MAX_SAFE_INTEGER);\n            setPassAliasesItems(filteredAliases);\n            memoisedPassAliasesItems = filteredAliases;\n            setUserHadVault(userHadVault);\n            setLoading(false);\n        }\n    };\n\n    useEffect(() => {\n        void initPassBridge().catch((error) => {\n            createNotification({\n                text: c('Error').t`Aliases could not be loaded`,\n                type: 'error',\n            });\n\n            throwError(new PassAliasesError(error, PASS_ALIASES_ERROR_STEP.INIT_BRIDGE));\n        });\n    }, [user, addresses]);\n\n    return {\n        hasReachedAliasesCountLimit: totalVaultAliasesCount >= passAliasesCountLimit,\n        getAliasOptions,\n        hasAliases: !!passAliasesItems.length,\n        hasUsedProtonPassApp: userHadVault,\n        loading,\n        hadInitialisedPreviously: Array.isArray(memoisedPassAliasesItems),\n        submitNewAlias,\n        passAliasesVaultName: passAliasVault?.content.name || '',\n        passAliasesItems,\n        passAliasesUpsellModal,\n    };\n};\n\nconst PassAliasesContext = createContext<ReturnType<typeof usePassAliasesSetup> | undefined>(undefined);\n\nexport const PassAliasesProvider = ({ children }: { children: React.ReactNode }) => {\n    const passAliasesSetup = usePassAliasesSetup();\n\n    return <PassAliasesContext.Provider value={passAliasesSetup}>{children}</PassAliasesContext.Provider>;\n};\n\n/**\n * Expose method calling the PassBridge API\n */\nexport const usePassAliasesContext = () => {\n    const context = useContext(PassAliasesContext);\n\n    if (context === undefined) {\n        throw new Error('usePassAliases must be used within a PassAliasesProvider');\n    }\n\n    return context;\n};\n","import { useEffect, useState } from 'react';\n\nimport debounce from 'lodash/debounce';\nimport { c } from 'ttag';\n\nimport { validateEmailAddress } from '@proton/shared/lib/helpers/email';\n\nimport type { CreateModalFormState } from '../../interface';\n\ntype FormErrors = Partial<Record<keyof CreateModalFormState, string>>;\ntype FormBlur = Partial<Record<keyof CreateModalFormState, boolean>>;\n\nconst MANDATORY_FIELDS: (keyof CreateModalFormState)[] = ['name', 'alias', 'mailbox', 'signedSuffix'];\n\nconst validateForm = (\n    formValues: CreateModalFormState,\n    blurred: FormBlur,\n    setErrors: (nextErrors: FormErrors | undefined) => void,\n    setHasErrors: (hasErrors: boolean) => void\n) => {\n    const nextErrors: FormErrors = {};\n\n    // Check if there are any errors in form\n    if (MANDATORY_FIELDS.some((key) => !formValues[key as keyof CreateModalFormState])) {\n        setHasErrors(true);\n    } else {\n        setHasErrors(false);\n    }\n\n    if (blurred.alias) {\n        if (!formValues.alias) {\n            nextErrors.alias = c('Error').t`Alias is required`;\n        }\n        if (!validateEmailAddress(formValues.alias)) {\n            nextErrors.alias = c('Error').t`Alias is not valid`;\n        }\n    }\n\n    if (blurred.name && !formValues.name) {\n        nextErrors.name = c('Error').t`Name is required`;\n    }\n\n    if (blurred.mailbox && !formValues.mailbox) {\n        nextErrors.mailbox = c('Error').t`Forward address is required`;\n    }\n\n    setErrors(Object.keys(nextErrors).length ? nextErrors : undefined);\n};\n\nconst throttleValidateForm = debounce(validateForm, 150);\n\nconst useCreateModalForm = () => {\n    const [formValues, setFormValues] = useState<CreateModalFormState>({\n        name: '',\n        alias: '',\n        mailbox: { email: '', id: 0 },\n        note: '',\n        signedSuffix: '',\n    });\n    /** Tells if form has at least one error */\n    const [hasErrors, setHasErrors] = useState<boolean>(false);\n    /** Contains the errors messages for each field input */\n    const [errors, setErrors] = useState<FormErrors>();\n    /** True if field input has triggered a blur event */\n    const [blurred, setBlurred] = useState<FormBlur>({\n        name: false,\n        alias: false,\n        mailbox: false,\n        note: false,\n    });\n\n    const [submitted, setSubmitted] = useState<boolean>(false);\n\n    useEffect(() => {\n        throttleValidateForm(formValues, blurred, setErrors, setHasErrors);\n    }, [formValues, blurred]);\n\n    return {\n        formValues,\n        setFormValues,\n        hasErrors,\n        errors,\n        blurred,\n        setBlurred,\n        submitted,\n        setSubmitted,\n    };\n};\n\nexport default useCreateModalForm;\n","import React, { useEffect, useState } from 'react';\n\nimport { c } from 'ttag';\n\nimport { Button } from '@proton/atoms/Button';\nimport { CircleLoader } from '@proton/atoms/CircleLoader';\nimport { Href } from '@proton/atoms/Href';\nimport { Input } from '@proton/atoms/Input';\nimport {\n    Form,\n    Icon,\n    IconName,\n    InputFieldTwo,\n    ModalProps,\n    ModalTwo,\n    ModalTwoContent,\n    ModalTwoFooter,\n    ModalTwoHeader,\n    Option,\n    SelectTwo,\n    TextAreaTwo,\n} from '@proton/components/components';\nimport { useNotifications } from '@proton/components/hooks';\nimport useIsMounted from '@proton/hooks/useIsMounted';\nimport { deriveAliasPrefix } from '@proton/pass/lib/validation/alias';\nimport type { AliasMailbox, AliasOptions } from '@proton/pass/types';\nimport { PASS_APP_NAME } from '@proton/shared/lib/constants';\nimport { traceInitiativeError } from '@proton/shared/lib/helpers/sentry';\nimport passAliasesLogo from '@proton/styles/assets/img/illustrations/pass-aliases-logo.svg';\nimport clsx from '@proton/utils/clsx';\n\nimport { usePassAliasesContext } from '../../PassAliasesProvider';\nimport { CreateModalFormState } from '../../interface';\nimport useCreateModalForm from './useCreatePassAliasesForm';\n\nimport './CreatePassAliasesForm.scss';\n\nconst FormGroupFieldWrapper = ({ children, classname }: { children: React.ReactNode; classname?: string }) => (\n    <div className={clsx('stacked-field-group', classname)}>{children}</div>\n);\n\nconst FormFieldWrapper = ({\n    children,\n    icon,\n    hasError,\n    isBigger,\n    isGroupElement,\n    classname,\n}: {\n    children: React.ReactNode;\n    icon?: IconName;\n    hasError?: boolean;\n    isBigger?: boolean;\n    isGroupElement?: boolean;\n    classname?: string;\n}) => (\n    <div\n        className={clsx(\n            'relative stacked-field border-weak px-4 py-3 flex items-center gap-x-4',\n            hasError && 'stacked-field--errors',\n            isBigger && 'stacked-field--bigger-field',\n            isGroupElement ? 'border-top border-left border-right' : 'border rounded-lg',\n            classname\n        )}\n    >\n        {icon && <Icon name={icon} className=\"shrink-0\" />}\n        <div className=\"flex-1\">{children}</div>\n    </div>\n);\n\ninterface Props {\n    onSubmit: () => void;\n    modalProps: ModalProps;\n    passAliasesURL: string;\n}\n\nconst CreatePassAliasesForm = ({ modalProps, onSubmit, passAliasesURL }: Props) => {\n    const { formValues, setFormValues, blurred, setBlurred, hasErrors, errors, submitted, setSubmitted } =\n        useCreateModalForm();\n    const { submitNewAlias, getAliasOptions } 