ter/PassAliases/PassAliasesError.ts","webpack://proton-drive/../../packages/pass/lib/validation/alias.ts","webpack://proton-drive/../../packages/pass/types/data/items.ts","webpack://proton-drive/../../packages/pass/lib/items/item.predicates.ts","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/PassAliases.helpers.ts","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/PassAliasesProvider.tsx","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/modals/CreatePassAliasesForm/useCreatePassAliasesForm.ts","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/modals/CreatePassAliasesForm/CreatePassAliasesForm.tsx","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/modals/PassAliasesUpsellModal.tsx","webpack://proton-drive/../../packages/pass/constants.ts","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/modals/TryProtonPass.tsx","webpack://proton-drive/../../packages/components/components/drawer/views/SecurityCenter/PassAliases/PassAliases.tsx"],"sourcesContent":["import { createBrowserHistory } from 'history';\n\nimport { decodeUtf8Base64, encodeUtf8Base64 } from '@proton/crypto/lib/utils';\nimport { authStore } from '@proton/pass/lib/auth/store';\nimport type { ItemFilters, ItemType, MaybeNull } from '@proton/pass/types';\nimport { partialMerge } from '@proton/pass/utils/object/merge';\nimport { getLocalIDPath } from '@proton/shared/lib/authentication/pathnameHelper';\n\nexport type ItemNewRouteParams = { type: ItemType };\n\nexport const history = createBrowserHistory();\n\n/** Appends the localID path to the provided path. If `localID` is not\n * defined returns the original path (this may be the case in the extension\n * for user's using legacy AuthSessions which were not persisted with the\n * session's LocalID */\nexport const getLocalPath = (path: string = '') => {\n    const localID = authStore.getLocalID();\n    return localID !== undefined ? `/${getLocalIDPath(localID)}/${path}` : `/${path}`;\n};\n\nexport const maybeTrash = (path: string, inTrash?: boolean) => `${inTrash ? 'trash/' : ''}${path}`;\n\n/** Resolves the item route given a shareId and an itemId. */\nexport const getItemRoute = (shareId: string, itemId: string, trashed?: boolean) =>\n    getLocalPath(maybeTrash(`share/${shareId}/item/${itemId}`, trashed));\n\nexport const getItemHistoryRoute = (shareId: string, itemId: string, trashed?: boolean) =>\n    `${getItemRoute(shareId, itemId, trashed)}/history`;\n\n/** Resolves the new item route given an item type. */\nexport const getNewItemRoute = (type: ItemType) => getLocalPath(`item/new/${type}`);\nexport const getTrashRoute = () => getLocalPath('trash');\nexport const getOnboardingRoute = () => getLocalPath('onboarding');\n\nconst INITIAL_FILTERS: ItemFilters = { search: '', sort: 'recent', type: '*', selectedShareId: null };\n\nexport const decodeFilters = (encodedFilters: MaybeNull<string>): ItemFilters =>\n    partialMerge(\n        INITIAL_FILTERS,\n        (() => {\n            try {\n                if (!encodedFilters) return {};\n                return JSON.parse(decodeUtf8Base64(encodedFilters));\n            } catch {\n                return {};\n            }\n        })()\n    );\n\nexport const decodeFiltersFromSearch = (search: string) => {\n    const params = new URLSearchParams(search);\n    return decodeFilters(params.get('filters'));\n};\n\nexport const encodeFilters = (filters: ItemFilters): string => encodeUtf8Base64(JSON.stringify(filters));\n","import type { Api } from '@proton/pass/types';\n\nexport let api: Api;\nexport const exposeApi = (value: Api) => (api = value);\n","import { c } from 'ttag';\n\nimport { api } from '@proton/pass/lib/api/api';\nimport type { AliasDetails, AliasMailbox, AliasOptions } from '@proton/pass/types';\n\nexport const getAliasOptions = async (shareId: string): Promise<AliasOptions> => {\n    const aliasOptions = await api({\n        url: `pass/v1/share/${shareId}/alias/options`,\n        method: 'get',\n    }).then(({ Options }) => {\n        if (!Options) throw new Error(c('Error').t`Alias options could not be resolved`);\n        return Options;\n    });\n\n    const options: AliasOptions = {\n        suffixes: aliasOptions.Suffixes.map((data) => ({\n            signedSuffix: data.SignedSuffix!,\n            suffix: data.Suffix!,\n            isCustom: data.IsCustom!,\n            domain: data.Domain!,\n        })),\n        mailboxes: aliasOptions.Mailboxes.map((mailbox) => ({\n            email: mailbox.Email,\n            id: mailbox.ID,\n        })),\n    };\n\n    return options;\n};\n\nexport const getAliasDetails = async (shareId: string, itemId: string): Promise<AliasDetails> => {\n    const result = await api({\n        url: `pass/v1/share/${shareId}/alias/${itemId}`,\n        method: 'get',\n    });\n\n    return {\n        aliasEmail: result.Alias!.Email,\n        mailboxes: result.Alias!.Mailboxes.map(({ Email, ID }): AliasMailbox => ({ id: ID, email: Email })),\n    };\n};\n\nexport const getAliasCount = async (): Promise<number> =>\n    (\n        await api({\n            url: `pass/v1/user/alias/count`,\n            method: 'get',\n        })\n    )?.AliasCount?.Total ?? 0;\n","import type { PassCryptoWorker } from '@proton/pass/types';\n\nexport let PassCrypto: PassCryptoWorker;\nexport const exposePassCrypto = (value: PassCryptoWorker) => (PassCrypto = value);\n","import type { OfflineConfig } from '@proton/pass/lib/cache/crypto';\nimport type { Maybe, SessionLockStatus, Store } from '@proton/pass/types';\nimport { encodedGetter, encodedSetter } from '@proton/pass/utils/store';\n\nimport type { AuthSessionVersion } from './session';\nimport { type AuthSession, SESSION_VERSION } from './session';\n\nexport type AuthStore = ReturnType<typeof createAuthStore>;\n\nconst PASS_ACCESS_TOKEN_KEY = 'pass:access_token';\nconst PASS_LOCAL_ID_KEY = 'pass:local_id';\nconst PASS_LOCK_LAST_EXTEND_TIME = 'pass:lock_extend_time';\nconst PASS_LOCK_STATUS_KEY = 'pass:lock_status';\nconst PASS_LOCK_TOKEN_KEY = 'pass:lock_token';\nconst PASS_LOCK_TTL_KEY = 'pass:lock_ttl';\nconst PASS_MAILBOX_PWD_KEY = 'pass:mailbox_pwd';\nconst PASS_OFFLINE_KD_KEY = 'pass:offline_kd';\nconst PASS_OFFLINE_CONFIG_KEY = 'pass:offline_config';\nconst PASS_REFRESH_TIME_KEY = 'pass:refresh_time';\nconst PASS_REFRESH_TOKEN_KEY = 'pass:refresh_token';\nconst PASS_SESSION_VERSION_KEY = 'pass:session_version';\nconst PASS_UID_KEY = 'pass:uid';\nconst PASS_USER_ID_KEY = 'pass:user_id';\n\nexport const createAuthStore = (store: Store) => {\n    const authStore = {\n        clear: () => store.reset(),\n\n        hasSession: (localID?: number) =>\n            Boolean(authStore.getUID() && (localID === undefined || authStore.getLocalID() === localID)),\n\n        getSession: (): AuthSession => ({\n            AccessToken: authStore.getAccessToken() ?? '',\n            keyPassword: authStore.getPassword() ?? '',\n            LocalID: authStore.getLocalID(),\n            payloadVersion: authStore.getSessionVersion(),\n            offlineConfig: authStore.getOfflineConfig(),\n            offlineKD: authStore.getOfflineKD(),\n            RefreshTime: authStore.getRefreshTime(),\n            RefreshToken: authStore.getRefreshToken() ?? '',\n            sessionLockToken: authStore.getLockToken(),\n            UID: authStore.getUID() ?? '',\n            UserID: authStore.getUserID() ?? '',\n        }),\n\n        setSession: (session: Partial<AuthSession>) => {\n            if (session.AccessToken) authStore.setAccessToken(session.AccessToken);\n            if (session.keyPassword) authStore.setPassword(session.keyPassword);\n            if (session.LocalID !== undefined) authStore.setLocalID(session.LocalID);\n            if (session.offlineConfig) authStore.setOfflineConfig(session.offlineConfig);\n            if (session.offlineKD) authStore.setOfflineKD(session.offlineKD);\n            if (session.RefreshTime) authStore.setRefreshTime(session.RefreshTime);\n            if (session.RefreshToken) authStore.setRefreshToken(session.RefreshToken);\n            if (session.sessionLockToken) authStore.setLockToken(session.sessionLockToken);\n            if (session.UID) authStore.setUID(session.UID);\n            if (session.UserID) authStore.setUserID(session.UserID);\n        },\n\n        setAccessToken: (accessToken: Maybe<string>): void => store.set(PASS_ACCESS_TOKEN_KEY, accessToken),\n        getAccessToken: (): Maybe<string> => store.get(PASS_ACCESS_TOKEN_KEY),\n        setRefreshToken: (refreshToken: Maybe<string>): void => store.set(PASS_REFRESH_TOKEN_KEY, refreshToken),\n        getRefreshToken: (): Maybe<string> => store.get(PASS_REFRESH_TOKEN_KEY),\n        setRefreshTime: (refreshTime: Maybe<number>) => store.set(PASS_REFRESH_TIME_KEY, refreshTime),\n        getRefreshTime: (): Maybe<number> => store.get(PASS_REFRESH_TIME_KEY),\n\n        setUID: (UID: Maybe<string>): void => store.set(PASS_UID_KEY, UID),\n        getUID: (): Maybe<string> => store.get(PASS_UID_KEY),\n        setUserID: (UserID: Maybe<string>): void => store.set(PASS_USER_ID_KEY, UserID),\n        getUserID: (): Maybe<string> => store.get(PASS_USER_ID_KEY),\n        setPassword: encodedSetter(store)(PASS_MAILBOX_PWD_KEY),\n        getPassword: encodedGetter(store)(PASS_MAILBOX_PWD_KEY),\n        setLocalID: (LocalID: Maybe<number>): void => store.set(PASS_LOCAL_ID_KEY, LocalID),\n        getLocalID: (): Maybe<number> => store.get(PASS_LOCAL_ID_KEY),\n\n        setOfflineKD: encodedSetter(store)(PASS_OFFLINE_KD_KEY),\n        getOfflineKD: encodedGetter(store)(PASS_OFFLINE_KD_KEY),\n        setOfflineConfig: (config: Maybe<OfflineConfig>) => store.set(PASS_OFFLINE_CONFIG_KEY, config),\n        getOfflineConfig: (): Maybe<OfflineConfig> => store.get(PASS_OFFLINE_CONFIG_KEY),\n\n        setLockStatus: (status: Maybe<SessionLockStatus>): void => store.set(PASS_LOCK_STATUS_KEY, status),\n        getLockStatus: (): Maybe<SessionLockStatus> => store.get(PASS_LOCK_STATUS_KEY),\n        setLockToken: encodedSetter(store)(PASS_LOCK_TOKEN_KEY),\n        getLockToken: encodedGetter(store)(PASS_LOCK_TOKEN_KEY),\n        setLockTTL: (ttl: Maybe<number>) => store.set(PASS_LOCK_TTL_KEY, ttl),\n        getLockTTL: (): Maybe<number> => store.get(PASS_LOCK_TTL_KEY),\n        setLockLastExtendTime: (extendTime: Maybe<number>): void => store.set(PASS_LOCK_LAST_EXTEND_TIME, extendTime),\n        getLockLastExtendTime: (): Maybe<number> => store.get(PASS_LOCK_LAST_EXTEND_TIME),\n\n        getSessionVersion: (): AuthSessionVersion => store.get(PASS_SESSION_VERSION_KEY) ?? SESSION_VERSION,\n        setSessionVersion: (version: AuthSessionVersion) => store.set(PASS_SESSION_VERSION_KEY, version),\n    };\n\n    return authStore;\n};\n\nexport let authStore: AuthStore;\nexport const exposeAuthStore = (value: AuthStore) => (authStore = value);\n","import type { VaultColor, VaultIcon } from '../protobuf/vault-v1';\n\nexport enum ShareType {\n    Vault = 1,\n    Item = 2,\n}\n\nexport enum ShareRole {\n    ADMIN = '1',\n    WRITE = '2',\n    READ = '3',\n}\n\nexport type VaultShareContent = {\n    description: string;\n    display: { icon?: VaultIcon; color?: VaultColor };\n    name: string;\n};\n\nexport type ItemShareContent = {};\n\nexport type ShareContent<T extends ShareType = ShareType> = T extends ShareType.Vault\n    ? VaultShareContent\n    : T extends ShareType.Item\n    ? ItemShareContent\n    : never;\n\nexport type ShareBase<T extends ShareType = ShareType> = {\n    content: ShareContent<T>;\n    createTime: number;\n    newUserInvitesReady: number;\n    owner: boolean;\n    shared: boolean;\n    shareId: string;\n    shareRoleId: ShareRole;\n    targetId: string;\n    targetMaxMembers: number;\n    targetMembers: number;\n    targetType: T;\n    vaultId: string;\n};\n\nexport type WithEventId<T> = T & { eventId: string };\nexport type Share<T extends ShareType = ShareType> = WithEventId<ShareBase<T>>;\n\nexport type ShareAccessKeys =\n    | 'newUserInvitesReady'\n    | 'owner'\n    | 'shared'\n    | 'shareId'\n    | 'shareRoleId'\n    | 'targetMaxMembers'\n    | 'targetMembers';\n","import noop from '@proton/utils/noop';\n\nexport type UnwrapPromise<T> = T extends any[]\n    ? { [K in keyof T]: UnwrapPromise<T[K]> }\n    : T extends Promise<infer U>\n      ? U\n      : T;\n\nexport type Awaiter<T> = Promise<T> & { resolve: (value: T | PromiseLike<T>) => void; reject: (err: unknown) => void };\nexport type AsyncResult<F extends (...args: any[]) => Promise<any>> = Promise<Awaited<ReturnType<F>>>;\n\nexport const awaiter = <T>(): Awaiter<T> => {\n    let resolver: (value: T | PromiseLike<T>) => void = noop;\n    let rejector: (err: unknown) => void = noop;\n\n    const promise = new Promise<T>((resolve, reject) => {\n        resolver = resolve;\n        rejector = reject;\n    }) as Awaiter<T>;\n\n    promise.resolve = resolver;\n    promise.reject = rejector;\n\n    return promise;\n};\n\n/**\n * this util will recursively unwrap promises in any\n * list like structure - it is useful in when working\n * with asynchronous & deeply nested data-structures.\n *\n * await unwrap([1,2,Promise.resolve(3)]) // [1,2,3]\n * await unwrap([1,2,[Promise.resolve(3)]) // [1,2,[3]]\n * await unwrap([[Promise.resolve(1)],[Promise.resolve(2)]]) // [[1],[2]]\n */\nexport const unwrap = async <T extends any[]>(arr: [...T]): Promise<UnwrapPromise<T>> =>\n    Promise.all(arr.map((value) => (Array.isArray(value) ? unwrap(value) : value))) as Promise<UnwrapPromise<T>>;\n\n/** Defines options for asynchronous function locking to manage concurrent executions */\ntype AsyncLockOptions<F extends (...args: any[]) => Promise<any>> = {\n    /** Optionally defines a key generator function to determine the lock key based on\n     * function parameters. This allows locking multiple function calls depending on\n     * parameters. If omitted, all function calls will be locked uniformly. */\n    key?: (...args: Parameters<F>) => string;\n};\n\n/** Creates a function that locks the execution of an asynchronous function to manage concurrency */\nexport const asyncLock = <F extends (...args: any[]) => Promise<any>>(fn: F, options?: AsyncLockOptions<F>) => {\n    const handlers = new Map<string, AsyncResult<F>>();\n\n    return (...args: Parameters<F>): AsyncResult<F> => {\n        const key = options?.key?.(...args) ?? '';\n        const pending = handlers.get(key) ?? fn(...args).finally(() => handlers.delete(key));\n        handlers.set(key, pending);\n\n        return pending;\n    };\n};\n\ntype AsyncQueueOptions<F extends (...args: any[]) => Promise<any>> = AsyncLockOptions<F>;\n\nexport const asyncQueue = <F extends (...args: any[]) => Promise<any>>(fn: F, options?: AsyncQueueOptions<F>) => {\n    const handlers = new Map<string, Promise<void>>();\n\n    return (async (...args: Parameters<F>) => {\n        const key = options?.key?.(...args) ?? '';\n        const queue = handlers.get(key) ?? Promise.resolve();\n        const job = awaiter<ReturnType<F>>();\n\n        handlers.set(\n            key,\n            queue.then(async () => {\n                try {\n                    const result = await fn(...args);\n                    job.resolve(result);\n                } catch (err) {\n                    job.reject(err);\n                }\n            })\n        );\n\n        return job;\n    }) as F;\n};\n\nexport type CancelablePromise<T> = Promise<T> & { cancel: () => void };\n\nexport const cancelable = <T>(promise: Promise<T>, canceled: boolean = false) => {\n    const cancelablePromise = new Promise(async (resolve, reject) => {\n        const result = await promise;\n        return canceled ? reject() : resolve(result);\n    }) as CancelablePromise<T>;\n\n    cancelablePromise.cancel = () => (canceled = true);\n\n    return cancelablePromise;\n};\n","import log from 'loglevel';\n\n/** re-import the globals in case any pass code\n * is loaded outside of our build pipeline */\nimport '../../globals.d';\n\nexport const logId = (id: string) =>\n    id.length > 10 ? `[${id.slice(0, 5)}…${id.slice(id.length - 5, id.length)}]` : `[${id}]`;\n\nexport const registerLoggerEffect = (effect: (...args: any[]) => void) => {\n    const originalFactory = log.methodFactory;\n\n    log.methodFactory = function (methodName, logLevel, loggerName) {\n        const originalMethod = originalFactory(methodName, logLevel, loggerName);\n\n        return function (...args: any[]) {\n            effect(...args);\n            if (ENV === 'development') originalMethod(...args);\n        };\n    };\n\n    log.rebuild();\n};\n\nlog.setLevel(\n    (() => {\n        if (typeof BUILD_TARGET === 'undefined' || typeof ENV === 'undefined') return 'SILENT';\n        return ENV === 'development' ? 'DEBUG' : 'INFO';\n    })(),\n    false\n);\n\nexport const logger = log;\n","import { stringToUtf8Array } from '@proton/crypto/lib/utils';\nimport type { PassEncryptionTag } from '@proton/pass/types';\nimport mergeUint8Arrays from '@proton/utils/mergeUint8Arrays';\n\nexport const KEY_LENGTH = 32;\nconst IV_LENGTH = 12;\nconst ALGORITHM = 'AES-GCM';\n\nexport const getSymmetricKey = async (key: Uint8Array): Promise<CryptoKey> =>\n    crypto.subtle.importKey('raw', key.slice(0, KEY_LENGTH).buffer, ALGORITHM, false, ['decrypt', 'encrypt']);\n\nexport const generateKey = (): Uint8Array => crypto.getRandomValues(new Uint8Array(KEY_LENGTH));\n\nexport const encryptData = async (key: CryptoKey, data: Uint8Array, tag: PassEncryptionTag) => {\n    const iv = crypto.getRandomValues(new Uint8Array(IV_LENGTH));\n    const cipher = await crypto.subtle.encrypt(\n        { name: ALGORITHM, iv, additionalData: stringToUtf8Array(tag) },\n        key,\n        data\n    );\n\n    return mergeUint8Arrays([iv, new Uint8Array(cipher)]);\n};\n\nexport const decryptData = async (key: CryptoKey, data: Uint8Array, tag: PassEncryptionTag) => {\n    const iv = data.slice(0, IV_LENGTH);\n    const cipher = data.slice(IV_LENGTH, data.length);\n    const result = await crypto.subtle.decrypt(\n        { name: ALGORITHM, iv, additionalData: stringToUtf8Array(tag) },\n        key,\n        cipher\n    );\n\n    return new Uint8Array(result);\n};\n","export class PassCryptoError extends Error {}\nexport class PassCryptoNotHydratedError extends PassCryptoError {}\nexport class PassCryptoHydrationError extends PassCryptoError {}\nexport class PassCryptoShareError extends PassCryptoError {}\nexport class PassCryptoVaultError extends PassCryptoError {}\nexport class PassCryptoItemError extends PassCryptoError {}\n\nexport const isPassCryptoError = (err: any) => err instanceof PassCryptoError;\n","import type { ItemState, Maybe, MaybeNull, ShareRole, ShareType } from '@proton/pass/types';\n\nexport enum PassEncryptionTag {\n    Cache = 'cache' /* web-only usage */,\n    Offline = 'offline',\n    ItemContent = 'itemcontent',\n    ItemKey = 'itemkey',\n    VaultContent = 'vaultcontent',\n}\n\nexport enum PassSignatureContext {\n    VaultInviteExistingUser = 'pass.invite.vault.existing-user',\n    VaultInviteNewUser = 'pass.invite.vault.new-user',\n}\n\nexport enum ContentFormatVersion {\n    Share = 1,\n    Item = 3,\n}\n\n/* type aliases */\nexport type Rotation = number;\nexport type ShareId = string;\n\nexport type RotationKey = {\n    key: CryptoKey;\n    raw: Uint8Array;\n    rotation: Rotation;\n};\n\nexport type VaultKey = RotationKey & { userKeyId: Maybe<string> };\nexport type ItemKey = RotationKey;\n\ntype OpenedShareBase = {\n    addressId: string;\n    createTime: number;\n    expireTime?: MaybeNull<number>;\n    newUserInvitesReady: number;\n    owner: boolean;\n    permission: number;\n    shared: boolean;\n    shareId: string;\n    shareRoleId: ShareRole;\n    targetId: string;\n    targetMaxMembers: number;\n    targetMembers: number;\n    vaultId: string;\n};\n\nexport type OpenedShare = OpenedShareBase &\n    (\n        | {\n              content: Uint8Array;\n              contentFormatVersion: number;\n              contentKeyRotation: Rotation;\n              targetType: ShareType.Vault;\n          }\n        | {\n              content: null;\n              contentFormatVersion: null;\n              contentKeyRotation: null;\n              targetType: ShareType.Item;\n          }\n    );\n\nexport type TypedOpenedShare<T extends ShareType> = Extract<OpenedShare, { targetType: T }>;\n\nexport type OpenedItem = {\n    aliasEmail: MaybeNull<string>;\n    content: Uint8Array;\n    contentFormatVersion: number;\n    createTime: number;\n    itemId: string;\n    lastUseTime: MaybeNull<number>;\n    modifyTime: number;\n    pinned: boolean;\n    revision: number;\n    revisionTime: number;\n    state: ItemState;\n};\n","import { CryptoProxy, VERIFICATION_STATUS } from '@proton/crypto';\nimport { getSymmetricKey } from '@proton/pass/lib/crypto/utils/crypto-helpers';\nimport { PassCryptoVaultError } from '@proton/pass/lib/crypto/utils/errors';\nimport type { ShareKeyResponse, VaultKey } from '@proton/pass/types';\nimport { base64StringToUint8Array } from '@proton/shared/lib/helpers/encoding';\nimport type { DecryptedKey } from '@proton/shared/lib/interfaces';\n\ntype OpenVaultKeyProcessParams = {\n    shareKey: ShareKeyResponse;\n    userKeys: DecryptedKey[];\n};\n\nexport const openVaultKey = async ({ shareKey, userKeys }: OpenVaultKeyProcessParams): Promise<VaultKey> => {\n    const { Key, KeyRotation, UserKeyID } = shareKey;\n    const privateUserKeys = userKeys.map(({ privateKey }) => privateKey);\n\n    const { data: vaultKey, verified } = await CryptoProxy.decryptMessage({\n        binaryMessage: base64StringToUint8Array(Key),\n        decryptionKeys: privateUserKeys,\n        verifica